baseline.sql:
SELECT MIN(GSserved) AS lowest_grade_served
FROM schools
WHERE NCESDist = '0632640' AND GSserved IS NOT NULL;

SELECT COUNT(DISTINCT name) AS num_release_promo_cards
FROM cards
WHERE isPromo = 1 AND promoTypes LIKE '%release%';

treatment.sql:
SELECT COUNT(*) AS num_rulings
FROM rulings
WHERE uuid IN (SELECT uuid FROM cards WHERE name = 'Fireball');

baseline.sql:
SELECT COUNT(DISTINCT language) AS num_foreign_languages
FROM set_translations
WHERE translation = 'Swamp';

SELECT COUNT(*) AS num_characters_no_race
FROM superhero
WHERE publisher_id = (
  SELECT publisher_id FROM superhero WHERE superhero_name = 'A-Bomb'
) 
AND race_id IS NULL;

SELECT ROUND(AVG(CAST(height_cm AS FLOAT)), 1) AS avg_height_cm
FROM superhero
WHERE race_id = (
    SELECT race_id FROM superhero WHERE superhero_name = 'A-Bomb'
) AND height_cm IS NOT NULL;

SELECT ROUND(
  100.0 * SUM(CASE WHEN Diagnosis = 'SLE' THEN 1 ELSE 0 END) / COUNT(*), 2
) AS SLE_percentage_among_thrombosis
FROM Examination
WHERE Thrombosis = 1;

SELECT MAX(CAST(RNP AS FLOAT)) AS max_anti_rnp_antibody
FROM Laboratory
WHERE CRE < 1.5 AND RNP IS NOT NULL;
